-- ============================================================================
-- prism_district_annual_vw: Congressional District Annual Climate Indicators
-- Sources: prism_district in congress.sqlite
-- Generated by: analysis/prism.R
-- ============================================================================

DROP VIEW IF EXISTS prism_district_annual_vw;

CREATE VIEW prism_district_annual_vw AS
SELECT 
    year,
    congress,
    state_code,
    district_number,
    ROUND(SUM(ppt), 2) AS total_precipitation_mm,
    ROUND(AVG(tmean), 2) AS mean_temp_c,
    ROUND(AVG((9.0 / 5.0) * tmean + 32.0), 2) AS mean_temp_f,
    ROUND(SUM(CASE WHEN ((9.0 / 5.0) * tmean + 32.0) > 65.0 THEN ((9.0 / 5.0) * tmean + 32.0) - 65.0 ELSE 0.0 END), 1) AS cool_deg_days,
    ROUND(SUM(CASE WHEN ((9.0 / 5.0) * tmean + 32.0) < 65.0 THEN 65.0 - ((9.0 / 5.0) * tmean + 32.0) ELSE 0.0 END), 1) AS heat_deg_days
FROM prism_district
WHERE tmean IS NOT NULL
GROUP BY year, congress, state_code, district_number;
